-- ============================================================
-- Этап 2 «Пол» эталона Homesteader's Cabin: тексты шагов 1–4 сверены с
-- ведомостью материалов (спека 007, поправки после закрытия 2026-09-28,
-- два захода). Источник текстов — ЭТАП2_Пол.md.
--   Шаг 1: рама в два слоя на всех четырёх сторонах (двойная линия на
--          Floor Framing, с. 3). Наружные торцевые доски — во всю ширину,
--          концами на опорных балках; порядок сборки — чтобы гвоздь 90 мм
--          проходил не больше 50 мм до следующей детали; стыки длинных
--          досок — посередине между лагами, у разных концов дома; рама к
--          балкам — саморезами 6×140 снаружи наискосок, бита TORX T30.
--   Шаг 2: лаги только на подвесах, подвес — ершёными гвоздями по схеме
--          производителя, подвес под сухую доску 45 мм; длина лаги сухой.
--   Шаг 3: ветрозащита — 5 полос поперёк дома; черновые бруски снизу по
--          плёнке; минвата 200 мм на 5 см ниже верха; лента пароизоляции —
--          между полотнами.
--   Шаг 4: только пояснения к «лаг…» и «шпунт…» (линтер SPEC 5.10) — в
--          скобках; в действии 3 повторные «лагам», «лаги» → «балкам», «балки».
-- Только update по изменённым полям: шаги не удаляются (на них ссылаются
-- отметки прогресса), id и sort не меняются.
-- Идемпотентно. Без этапа 312 — тихо пропуск (как 017).
-- ============================================================

do $do$
begin
  if not exists (select 1 from stages
                 where id = 'de300000-0000-4000-8000-000000000312') then
    return;
  end if;

  update steps set
    why_text = 'Сначала собираем «периметр» — прямоугольную рамку из толстых досок по краю. Рама у нас двойная: на каждой стороне по две доски, сшитые вместе, — так на чертеже, и так крепче. Наружные доски на коротких сторонах дома (торцах) идут во всю ширину дома: их концы лежат на опорных балках, и торец дома опирается на балки, а не висит на гвоздях. Это скелет, к которому потом крепятся все остальные балки. От того, насколько ровный этот прямоугольник, зависит весь дом.',
    prep_text = 'Купи заранее (из сметы): доски 50×250 мм на раму — по две на каждую сторону; гвозди 90 мм; длинные саморезы по дереву 6×140 мм — крепить раму к опорным балкам; бита TORX T30 (звёздочка) — насадка к шуруповёрту под головку этих саморезов.',
    actions = '["Дом у нас 3,66 м в ширину и 7,32 м в длину. Рама — в два слоя: на каждой стороне по две доски 50×250 «на ребро» (высокой стороной вверх). Собирай строго в том порядке, как ниже. Первое кольцо — на опорных балках, которые уложил в Этапе 1: на короткие стороны дома положи две доски во всю ширину, по 3,66 м, концами на балки, вровень с их наружным краем. Между ними — две длинные доски, отступив 5 см (у сухой — 4,5 см) от наружного края балок: туда потом встанет второй слой.","Длинная доска — около 7,22 м (у сухой — 7,23 м), из двух кусков: 5,75 м и вставка около 1,47 м (у сухой — 1,48 м) — её точную длину отмерь по месту между досками. Стык делай в 1,52 м от края дома: так он придётся посередине между будущими балками пола, а не там, где встанет подвес (стальной «карман» для балки, шаг 2). У обеих длинных сторон стык — у одного и того же конца дома.","Соедини углы кольца: короткая доска закрывает конец длинной — забей 3 гвоздя 90 мм через короткую доску в торец (срез) длинной.","Проверь диагонали! Измерь рамку из угла в угол крест-накрест. Обе диагонали должны совпасть (разница ≤5 мм) — тогда прямоугольник ровный. Если не совпали — двигай раму, пока не сравняются.","Второй слой — сначала короткие стороны. Изнутри к каждой короткой доске приставь ещё одну, 3,46 м (у сухой — 3,48 м): она встаёт между длинными досками, точную длину отмерь по месту между досками. Прибей её сразу, пока снаружи нет второй длинной доски: с каждого конца 3 гвоздя 90 мм через длинную доску — гвоздь проходит её 5 см и на 4 см входит в торец короткой. Через две доски сразу (10 см) гвоздь 90 мм не достанет.","Теперь длинные стороны: снаружи к каждой длинной доске приложи ещё одну — она ложится на балку в оставленный отступ. Она тоже из куска 5,75 м и вставки, но стык сделай у другого конца дома (тоже в 1,52 м от края), чтобы он не пришёлся напротив первого. Углы — по 3 гвоздя 90 мм через наружную короткую доску в торец длинной.","Сшей слои — то есть сбей две доски в одну толстую: гвозди 90 мм через каждые 40 см, по 2 (один выше, другой ниже) на всех четырёх сторонах.","Прикрепи раму к опорным балкам длинными саморезами 6×140. Вкручивай их снаружи рамы, наискосок — под углом примерно 45°, примерно в 5 см от низа доски, вниз в балку. По длинным сторонам — через каждые 60 см, первый и последний в 15 см от угла. На коротких сторонах — по одному саморезу в каждый конец наружной доски, там, где она лежит на балке."]',
    tools = '{"молоток","шуруповёрт","рулетка 10 м","угольник","уровень","карандаш"}',
    self_check = '["Рама 3,66 × 7,32 м собрана в два слоя, доски на ребре","Наружные короткие доски — во всю ширину, концами лежат на опорных балках","Углы скреплены (по 3 гвоздя в каждом углу каждого слоя)","Диагонали совпали (разница ≤5 мм)","Слои сшиты гвоздями через 40 см, стыки длинных досок — у разных концов дома","Рама прикручена к опорным балкам саморезами снаружи, наискосок: через 60 см по длинным сторонам и в концах наружных коротких досок"]',
    hint = 'Доски 50×250 длинные и тяжёлые. Ставь их на ребро (высокой стороной вверх) — так они держат нагрузку. Плашмя класть нельзя, прогнутся. Гвозди сшивки ставь один выше, другой ниже, а не в одну линию — так доска не треснет.'
  where id = 'de300000-0000-4000-8000-000000000431';

  update steps set
    title = 'Ставим лаги (балки пола)',
    why_text = 'Внутри рамы через равные промежутки ставим поперечные балки, на которые ляжет настил. Их называют лагами (это просто балки пола). Чем чаще они стоят, тем крепче пол и тем меньше он «играет» под ногами.',
    prep_text = 'Купи заранее (из сметы): доски 50×250 мм — длиной по ширине дома, 3,46 м (у сухой — 3,48 м) между рамой, точную длину отмерь по месту между досками; подвесы (стальные «карманы» для концов балок) — по два на каждую балку; ершёные гвозди 4×40 для подвесов. Если доска сухая строганая, она тоньше — 45 мм, и подвес для неё свой, шириной 45 мм (в смете он подставится сам, если выбрана сухая доска).',
    actions = '["Размечай на раме места балок: они ставятся через каждые 61 см (это шаг 610 мм — стандарт, лист настила ровно ляжет краями). Отметь карандашом на обеих длинных сторонах рамы.","На каждую метку поставь подвес (стальной «карман» для конца балки) так, чтобы балка в нём встала вровень с верхом рамы.","Прибей подвес ершёными гвоздями 4×40 (ершёный гвоздь — с насечками, держит крепче обычного) по схеме производителя подвеса — она на упаковке или на сайте. Для доски тоньше 6 см гвозди ставят не во все отверстия, а примерно в половину — иначе доска треснет.","Вставь балку 50×250 в подвесы с обеих сторон, на ребро, и прибей её к подвесу по той же схеме. Балку крепи только на подвесах — гвозди наискосок вместо подвеса не годятся.","Проверь уровнем, что все балки вровень — по ним пойдёт ровный настил."]',
    tools = '{"молоток","рулетка 10 м","карандаш","уровень"}',
    self_check = '["Места балок размечены через 61 см","Все балки стоят в подвесах с обоих концов","Подвесы прибиты ершёными гвоздями по схеме производителя","Балки вровень с верхом рамы (проверено уровнем)"]',
    hint = 'Шаг 61 см выбран не случайно — это чтобы стандартный лист фанеры (122 см) лёг ровно краями на балки. Не меняй шаг, иначе настил повиснет в воздухе. Сухая строганая доска тоньше обычной — 45 мм вместо 50: для неё бери подвес шириной 45 мм, в широком она будет болтаться.',
    common_mistake = 'Ставить балки «примерно», на глаз. Тогда край фанеры попадёт мимо балки, пол будет прогибаться. Меряй каждую по метке.'
  where id = 'de300000-0000-4000-8000-000000000432';

  update steps set
    why_text = 'Между балками пола укладываем утеплитель — иначе через пол будет тянуть холодом снизу, а зимой пол будет ледяным. В США этот дом строят без утепления (тёплый климат), но для нас это обязательно.',
    prep_text = 'Купи заранее (из сметы): минеральную вату плитами 100 мм — в два слоя; ветрозащитную плёнку (снизу) и пароизоляционную (сверху); соединительную ленту для стыков пароизоляции; черновые бруски 50×50 мм — держать утеплитель снизу; гвозди 90 мм.',
    actions = '["Снизу на балки натяни ветрозащитную плёнку: 5 полос поперёк дома — от одной длинной стороны рамы до другой, с запасом по 10 см на раму с каждой стороны, — внахлёст на 10–15 см, прихвати степлером.","Снизу, прямо по плёнке, поперёк балок — вдоль дома — прибей черновые бруски 50×50: 5 рядов через 58 см по ширине, у самой рамы ряд не нужен. Стыки брусков делай только на балке. В каждую балку — по гвоздю 90 мм, на стыке — по гвоздю в конец каждого бруска. Бруски держат плёнку и утеплитель, чтобы не выпали.","Уложи плиты минваты между балками в два слоя по 100 мм, плотно, без щелей (в щели уходит тепло). Толщина ~200 мм — на 5 см ниже верха лаги (балки пола): этот зазор оставь пустым.","Сверху накрой пароизоляционной плёнкой (не даёт влаге из дома мочить утеплитель): три полосы вдоль дома внахлёст на 10–15 см, прихвати степлером. Стыки проклей соединительной лентой по всей длине — лента идёт между полотнами: приклей ленту к краю нижнего полотна, сними защитную бумагу, прижми край следующего полотна."]',
    tools = '{"степлер строительный","нож","молоток","рулетка 10 м"}',
    self_check = '["Снизу натянута ветрозащита (5 полос поперёк дома внахлёст), бруски прибиты, утеплитель не выпадает","Минвата в два слоя, плотно, без щелей (~200 мм, на 5 см ниже верха балок)","Сверху пароизоляция, стыки проклеены лентой между полотнами"]',
    hint = 'Утеплитель кроит легко — обычным ножом или ножовкой. Режь чуть шире промежутка (на 1-2 см), чтоб вставал враспор и не оставлял щелей. Швы второго слоя смещай относительно первого — так холоду негде пройти.'
  where id = 'de300000-0000-4000-8000-000000000433';

  -- Шаг 4: только пояснения к жаргону (лаг…, шпунт…), остальной текст — как в 017
  update steps set
    why_text = 'Поверх лаг (балок пола) и утеплителя кладём листы фанеры — это и есть черновой пол, по которому будешь ходить. На него потом ляжет чистовое покрытие (ламинат, доска).',
    actions = '["Начинай с угла. Клади первый лист фанеры на лаги, край листа должен попадать на середину лаги (чтобы соседний лист тоже на неё опёрся).","Шпунтованная фанера соединяется «в замок» (паз-гребень) — стыкуй листы плотно, без зазоров.","Прикручивай фанеру к лагам (балкам пола) саморезами каждые 20 см по всем балкам. Можно промазать балки клеем перед укладкой — пол не будет скрипеть.","Раскладывай листы с разбежкой швов — как кирпичная кладка, чтобы стыки не совпадали в линию (так пол крепче)."]',
    hint = '«Шпунтованная» значит с замком по краям (паз и гребень) — листы защёлкиваются друг в друга, пол получается монолитным, без щелей. Обычную фанеру брать не стоит — будут зазоры.

СКРИПТ — покупка пиломатериала на пол (доски 50×250 и фанера). На доске 50×250 (это дорогая крупная доска) и на фанере часто обманывают — на влажности, сорте, кубатуре. Спрашивай про доски 50×250: «Естественной влажности или сухая?» — для лаг пола лучше сухая (не поведёт под нагрузкой), естественной влажности дешевле, но может «крутить»; «Сорт 1 или 2?» — для несущих лаг (балок пола) только 1-2 сорт, без крупных сучков и трещин; «Посчитайте кубатуру при мне». Спрашивай про фанеру: «Шпунтованная (с замком) или обычная?» — нам нужна шпунтованная (с замком) для пола; «Какой сорт и влагостойкость?» — для пола ФК или ФСФ, толщина 18 мм. Красные флаги: доски синие, чёрные пятна, плесень — гнилой товар, не бери; «влажность нормальная, не парься» — значит сырая, лаги (балки пола) поведёт; «кубатуру на глаз» — обвесят. Проверка кубатуры доски 50×250: одна доска 6 м × 0,25 м × 0,05 м = 0,075 м³, значит в 1 кубе таких досок 1 ÷ 0,075 ≈ 13 досок. Дают меньше за «куб» — считай при них. Ориентир: доска 50×250 дороже обычной (широкая). Фанера 18 мм шпунт — от ~1500-2000 ₽ за лист (уточняй в регионе).'
  where id = 'de300000-0000-4000-8000-000000000434';
end
$do$;
